try:
    d=json.load(open(p))
except Exception as e:
    print("ERR",e); raise SystemExit
msgs=d.get('conversation') or d.get('messages') or d
if isinstance(msgs,dict): msgs=msgs.get('messages',[])
out=[]
for m in msgs[-30:]:
    role=m.get('role')
    for c in m.get('content',[]):
        t=c.get('text') or ''
        if c.get('type')=='toolRequest':
            t='TOOL '+json.dumps(c.get('toolCall',{}).get('value',{}).get('arguments',{}))[:400]
        elif c.get('type')=='toolResponse':
            t='RESP '+json.dumps(c.get('toolResult',{}))[:300]
        if t: out.append(f"[{role}] {t[:600]}")
print("\n".join(out[-25:]))
EOF

